# Co-DM panel (host-62f7a4.com). Cloudflare-proxied; wildcard *.host-f2a6b6.com cert.
# Locked by HTTP basic auth. Set the password once:
#   sudo htpasswd -c /etc/nginx/.label-redacted.htpasswd name-redacted
server {
    listen 443 ssl http2;
    server_name host-62f7a4.com;
    ssl_certificate     /etc/letsencrypt/live/host-525a57.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/host-525a57.com/privkey.pem;

    # Match the app's own MAX_BODY_BYTES (32MB). nginx defaults to 1MB, which
    # silently killed a 4.2MB PDF upload before it ever reached the app: the
    # client got a 413 HTML error page and reported "Unexpected token '<'".
    # This must be >= the app's limit, or the app's own error message is a lie.
    client_max_body_size 32m;

    auth_basic "Co-DM";
    auth_basic_user_file /etc/nginx/.label-redacted.htpasswd;

    # The press kit is public: it is collateral meant to be sent to people who
    # do not have panel credentials. Everything under /press/ is generated from
    # docs/marketing and docs/whitepaper.md and carries nothing private. The
    # prefix match (^~) beats the regex locations and covers both /press and
    # /press/, because the app's 301 to the trailing slash would otherwise be
    # issued behind the auth prompt.
    location ^~ /press {
        auth_basic off;
        proxy_pass http://127.0.0.1:5150;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header Connection "";
        proxy_buffering off;
    }

    location / {
        proxy_pass http://127.0.0.1:5150;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header Connection "";
        proxy_buffering off;
        proxy_read_timeout 900s;
    }
}

