# /etc/nginx/sites-available/host-492568.ai on word-1ef544.
# Reverse proxy fronting the LiteLLM broker (127.0.0.1:4000) so off-box consumers
# (dev-box agents, word-51eb89 apps, GitHub CI) reach it with their virtual key.
# Grey-clouded (DNS-only) -> end-to-end TLS to origin, no Cloudflare 100s cap.
# Cert issued by: certbot certonly/--nginx -d host-492568.ai (auto-renews).
server {
    listen 80;
    listen [::]:80;
    server_name host-492568.ai;
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name host-492568.ai;

    ssl_certificate     /etc/letsencrypt/live/host-492568.ai/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/host-492568.ai/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;

    client_max_body_size 25m;

    location / {
        proxy_pass http://127.0.0.1:4000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        # Streaming (SSE) chat completions -- don't buffer, allow long turns.
        proxy_buffering off;
        proxy_cache off;
        proxy_read_timeout 600s;
        proxy_send_timeout 600s;
    }
}

